# === Already-up fast path (#219) ===
# The flock above stops two invocations racing. It does NOT stop the far more
# common SEQUENTIAL double-boot: in one verify run the platform starts the
# stack, the init-dev-server boot-smoke starts it again and then kills it, and
# verify-work's step 1 then finds a dead port and starts it a third time. So:
# if this project's ready ports are already answering AND nothing has changed
# that a restart would pick up, the boot is already done. Exit 0 and let the
# caller poll the port, exactly as the lock branch does.
#
# "Nothing has changed" is TWO facts, and both are load-bearing:
#   * the resolved compose config is byte-identical, and
#   * git HEAD has not moved.
#
# Escape hatch: PIVOTA_DEV_FORCE_RESTART=1 always does the full boot.
READY_PORTS="5173 8080"
DEV_STATE="/tmp/pivota-dev-boot-state"
dev_boot_state() {
  # Cheap, deterministic, and quiet. `compose config` resolves env/overrides,
  # so it changes whenever anything that would alter a container changes.
  # Missing docker or no compose file -> the compose half is simply empty.
  printf '%s|%s' \
    "$(git rev-parse HEAD 2>/dev/null || echo no-git)" \
    "$(docker compose config 2>/dev/null | sha256sum 2>/dev/null | cut -d' ' -f1)"
}
dev_ports_answering() {
  local p ok=1
  [ -n "${READY_PORTS// /}" ] || return 1
  for p in $READY_PORTS; do
    if (exec 3<>"/dev/tcp/127.0.0.1/$p") 2>/dev/null; then exec 3>&-; ok=0; fi
  done
  return $ok
}
dev_compose_healthy() {
  # Only meaningful for a compose app. `config --services` is the presence
  # test that actually works: it succeeds exactly when a compose file exists
  # AND parses (a filename glob exits non-zero on the other spelling).
  docker compose config --services >/dev/null 2>&1 || return 0   # not compose -> nothing to check
  local rows
  rows="$(docker compose ps --all 2>/dev/null | tail -n +2 || true)"
  [ -n "$rows" ] || return 1
