# === Optional pre-exec snippet (JDK install, rustup, golang one-shot setup) ===
# Shape B (compose.md): `docker-compose.yml` declares ONLY pre-built-image
# datastores (db=postgis/postgis, nats, opa, keycloak) — none has a `build:`
# directive, so compose is not the app here. Bring the datastores up
# detached and wait for their healthchecks; the app itself runs natively via
# the multi-process block below. This step needs no node_modules, so it runs
# BEFORE install (never run anything requiring node_modules in this slot).
echo "[pivota] bringing up datastore services (db, nats, opa, keycloak) via docker compose"
if ! docker compose up -d --wait db nats opa keycloak 2>/dev/null; then
  docker compose up -d db nats opa keycloak
  echo "[pivota] 'docker compose up --wait' unsupported or a healthcheck is slow — falling back to a fixed grace period"
  sleep 5
fi

