# build finishes correctly moments later. Doing the build HERE — before the
# multi-process block spawns anything — makes that ordering impossible by
# construction, the same "ordering must be a hard dependency, not a race"
# principle as the backend's migrate-before-serve step below.
echo "[pivota] building frontend/design-system (one-time; frontend/app's dep-scan needs dist/ to exist before it starts)"
( cd frontend/design-system && npm run build )

# === Multi-process supervision (compose.md Shape B: 3 native app processes) ===
# The repo's own root `npm run dev` script already declares this same shape
# (datastores detached, design-system built synchronously, then
# design-system-watch/backend/frontend concurrently) but via `concurrently`,
# which init-dev-server's anti-patterns forbid introducing in a generated
# wrapper. This is the canonical bash `trap` + `wait -n` block from
# multi-process-template.md §2, verbatim except for the four {{PROC_N_*}}
# placeholders per child.
shutdown() {
  echo "[pivota] shutting down children"
  kill -TERM "${PIDS[@]}" 2>/dev/null || true
  # Brief grace, then SIGKILL stragglers (npm SIGTERM)
  sleep 2
  kill -KILL "${PIDS[@]}" 2>/dev/null || true
  wait
}
trap shutdown SIGTERM SIGINT EXIT

declare -a PIDS=()

# design-system: dist/ already exists (synchronous build above) — this is
# watch-mode only, for live rebuilds on source edits.
(
  cd 'frontend/design-system' \
    && : \
    && exec bash -c 'exec npm run dev'
) 2>&1 | sed 's/^/[design-system] /' &
PIDS+=($!)

# backend: migrate then idempotent seed (runtime-environment.md §3 — a
# migrated-but-unseeded DB has no login user, so the preview is unusable)
# BEFORE the dev server. Non-fatal (`;`, not `&&`) so a transient hiccup
# doesn't strand boot; failures are logged loudly either way.
(
  cd 'backend' \
    && : \
    && exec bash -c 'npm run migrate || echo "[pivota] WARN backend migrate failed — starting dev server anyway"; npm run seed || echo "[pivota] WARN backend seed failed — starting dev server anyway"; exec npm run dev'
) 2>&1 | sed 's/^/[backend] /' &
PIDS+=($!)

# frontend: Vite dev server (binds 0.0.0.0:5173 per vite.config.ts + --host flag).
(
  cd 'frontend/app' \
    && : \
    && exec bash -c 'exec npm run dev'
) 2>&1 | sed 's/^/[frontend] /' &
PIDS+=($!)

# Wait for ANY child to exit; if one dies, the trap tears down siblings.
wait -n
EXIT_CODE=$?
shutdown
exit "$EXIT_CODE"
